package com.cognia.api.adapter.out.persistence;

import com.cognia.api.application.port.out.*;
import com.cognia.api.domain.model.*;
import jakarta.persistence.EntityManager;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

@Repository @Transactional
public class ReviewJpaRepositoryAdapter implements ReviewDeckPort, ReviewRepository, GlobalExamRepository {
	private final EntityManager em;
	private final ReviewJpaMapper mapper=new ReviewJpaMapper();
	public ReviewJpaRepositoryAdapter(EntityManager em){this.em=em;}
	@Override @Transactional(readOnly=true) public List<ReviewCard> activeCards(UUID concept){return em.createNativeQuery("select id,concepto_id,anverso_pregunta,reverso_respuesta,pista from tarjeta_repaso where concepto_id=:concept and activa=true order by id").setParameter("concept",concept).getResultList().stream().map(row->mapper.toCardDomain((Object[])row)).toList();}
	@Override @Transactional(readOnly=true) public Optional<ReviewCard> card(UUID card){return em.createNativeQuery("select id,concepto_id,anverso_pregunta,reverso_respuesta,pista from tarjeta_repaso where id=:id").setParameter("id",card).getResultList().stream().map(row->mapper.toCardDomain((Object[])row)).findFirst();}
	@Override public void addMissingProgress(UUID student,UUID concept,List<ReviewCard> cards,Instant firstDueAt){for(var card:cards)em.createNativeQuery("insert into progreso_repaso (estudiante_id,tarjeta_id,concepto_id,fecha_proximo_repaso) values (:student,:card,:concept,:due) on conflict (estudiante_id,tarjeta_id) do nothing").setParameter("student",student).setParameter("card",card.id()).setParameter("concept",concept).setParameter("due",firstDueAt).executeUpdate();}
	@Override @Transactional(readOnly=true) public List<ReviewProgress> due(UUID student,UUID subject,Instant now,int limit){return em.createNativeQuery("select p.id,p.estudiante_id,p.tarjeta_id,p.concepto_id,p.factor_facilidad,p.intervalo_dias,p.repeticiones_consecutivas,p.fallos_acumulados,p.fallos_consecutivos,p.fecha_ultimo_repaso,p.fecha_proximo_repaso,p.estado from progreso_repaso p join concepto c on c.id=p.concepto_id join tarjeta_repaso card on card.id=p.tarjeta_id and card.concepto_id=p.concepto_id where p.estudiante_id=:student and c.asignatura_id=:subject and card.activa=true and p.fecha_proximo_repaso<=:now order by p.fecha_proximo_repaso,p.id").setParameter("student",student).setParameter("subject",subject).setParameter("now",now).setMaxResults(limit).getResultList().stream().map(row->mapper.toProgressDomain((Object[])row)).toList();}
	@Override @Transactional(readOnly=true) public Optional<ReviewProgress> progress(UUID student,UUID subject,UUID id){return em.createNativeQuery("select p.id,p.estudiante_id,p.tarjeta_id,p.concepto_id,p.factor_facilidad,p.intervalo_dias,p.repeticiones_consecutivas,p.fallos_acumulados,p.fallos_consecutivos,p.fecha_ultimo_repaso,p.fecha_proximo_repaso,p.estado from progreso_repaso p join concepto c on c.id=p.concepto_id where p.id=:id and p.estudiante_id=:student and c.asignatura_id=:subject").setParameter("id",id).setParameter("student",student).setParameter("subject",subject).getResultList().stream().map(row->mapper.toProgressDomain((Object[])row)).findFirst();}
	@Override public void resetConsecutiveLapses(UUID student,UUID concept){em.createNativeQuery("update progreso_repaso set fallos_consecutivos=0 where estudiante_id=:student and concepto_id=:concept").setParameter("student",student).setParameter("concept",concept).executeUpdate();}
	@Override public ReviewSession findOrStartSession(UUID student,UUID subject,Instant now){var existing=em.createNativeQuery("select id,estudiante_id,asignatura_id,fecha_inicio,fecha_fin,total_tarjetas_revisadas,total_recordadas,total_olvidadas from sesion_repaso where estudiante_id=:student and asignatura_id=:subject and fecha_fin is null order by fecha_inicio desc limit 1").setParameter("student",student).setParameter("subject",subject).getResultList();if(!existing.isEmpty())return mapper.toSessionDomain((Object[])existing.get(0));var id=UUID.randomUUID();em.createNativeQuery("insert into sesion_repaso(id,estudiante_id,asignatura_id,fecha_inicio) values (:id,:student,:subject,:started)").setParameter("id",id).setParameter("student",student).setParameter("subject",subject).setParameter("started",now).executeUpdate();return new ReviewSession(id,student,subject,now,null,0,0,0);}
	@Override @Transactional(readOnly=true) public Optional<ReviewSession> session(UUID student,UUID id){return em.createNativeQuery("select id,estudiante_id,asignatura_id,fecha_inicio,fecha_fin,total_tarjetas_revisadas,total_recordadas,total_olvidadas from sesion_repaso where id=:id and estudiante_id=:student").setParameter("id",id).setParameter("student",student).getResultList().stream().map(row->mapper.toSessionDomain((Object[])row)).findFirst();}
	@Override @Transactional(readOnly=true) public List<ReviewAnswer> reviewAnswers(UUID id){return em.createNativeQuery("select id,sesion_repaso_id,progreso_repaso_id,calificacion_sm2,intervalo_anterior_dias,intervalo_nuevo_dias,factor_facilidad_nuevo from detalle_respuesta_repaso where sesion_repaso_id=:id order by id").setParameter("id",id).getResultList().stream().map(row->mapper.toAnswerDomain((Object[])row)).toList();}
	@Override public ReviewAnswer saveGrade(UUID session,ReviewProgress next,int grade,int oldInterval){em.createNativeQuery("update progreso_repaso set factor_facilidad=:ease,intervalo_dias=:interval,repeticiones_consecutivas=:repetitions,fallos_acumulados=:totalLapses,fallos_consecutivos=:consecutiveLapses,fecha_ultimo_repaso=:lastReviewed,fecha_proximo_repaso=:nextReview,estado=:state where id=:id").setParameter("ease",next.easeFactor()).setParameter("interval",next.intervalDays()).setParameter("repetitions",next.repetitions()).setParameter("totalLapses",next.totalLapses()).setParameter("consecutiveLapses",next.consecutiveLapses()).setParameter("lastReviewed",next.lastReviewedAt()).setParameter("nextReview",next.nextReviewAt()).setParameter("state",next.state().name()).setParameter("id",next.id()).executeUpdate();var answerId=UUID.randomUUID();em.createNativeQuery("insert into detalle_respuesta_repaso(id,sesion_repaso_id,progreso_repaso_id,calificacion_sm2,intervalo_anterior_dias,intervalo_nuevo_dias,factor_facilidad_nuevo) values (:id,:session,:progress,:grade,:oldInterval,:newInterval,:ease)").setParameter("id",answerId).setParameter("session",session).setParameter("progress",next.id()).setParameter("grade",grade).setParameter("oldInterval",oldInterval).setParameter("newInterval",next.intervalDays()).setParameter("ease",next.easeFactor()).executeUpdate();return new ReviewAnswer(answerId,session,next.id(),grade,oldInterval,next.intervalDays(),next.easeFactor());}
	@Override public ReviewSession finish(ReviewSession session,Instant at){var answers=reviewAnswers(session.id());var remembered=(int)answers.stream().filter(a->a.grade()>=3).count();var forgotten=answers.size()-remembered;em.createNativeQuery("update sesion_repaso set fecha_fin=:finished,total_tarjetas_revisadas=:reviewed,total_recordadas=:remembered,total_olvidadas=:forgotten where id=:id").setParameter("finished",at).setParameter("reviewed",answers.size()).setParameter("remembered",remembered).setParameter("forgotten",forgotten).setParameter("id",session.id()).executeUpdate();return new ReviewSession(session.id(),session.studentId(),session.subjectId(),session.startedAt(),at,answers.size(),remembered,forgotten);}
	@Override @Transactional(readOnly=true) public boolean hasCurrentCompletedPath(UUID student,UUID subject){var latest=em.createQuery("select p from LearningPathJpaEntity p where p.studentId=:student and p.subjectId=:subject order by p.version desc",LearningPathJpaEntity.class).setParameter("student",student).setParameter("subject",subject).setMaxResults(1).getResultList();return !latest.isEmpty()&&"COMPLETADA".equals(latest.get(0).getState());}
	@Override @Transactional(readOnly=true) public Optional<GlobalExam> inProgress(UUID student,UUID subject){return em.createQuery("select s from DiagnosticSessionJpaEntity s where s.studentId=:student and s.subjectId=:subject and s.type='EXAMEN_GLOBAL' and s.state='EN_PROGRESO' order by s.attempt",DiagnosticSessionJpaEntity.class).setParameter("student",student).setParameter("subject",subject).setMaxResults(1).getResultList().stream().map(mapper::toDomain).findFirst();}
	@Override @Transactional(readOnly=true) public List<GlobalExam> exams(UUID student,UUID subject){return em.createQuery("select s from DiagnosticSessionJpaEntity s where s.studentId=:student and s.subjectId=:subject and s.type='EXAMEN_GLOBAL' order by s.attempt",DiagnosticSessionJpaEntity.class).setParameter("student",student).setParameter("subject",subject).getResultList().stream().map(mapper::toDomain).toList();}
	@Override @Transactional(readOnly=true) public Optional<GlobalExam> find(UUID student,UUID id){return em.createQuery("select s from DiagnosticSessionJpaEntity s where s.id=:id and s.studentId=:student and s.type='EXAMEN_GLOBAL'",DiagnosticSessionJpaEntity.class).setParameter("id",id).setParameter("student",student).setMaxResults(1).getResultList().stream().map(mapper::toDomain).findFirst();}
	@Override public GlobalExam save(GlobalExam exam){if(exam.id()==null){var row=new DiagnosticSessionJpaEntity(exam.studentId(),exam.subjectId(),exam.attempt());em.persist(row);em.flush();return mapper.toDomain(row);}var row=em.find(DiagnosticSessionJpaEntity.class,exam.id());if(row==null||!"EXAMEN_GLOBAL".equals(row.getType()))throw new IllegalArgumentException("Global exam was not found");if("COMPLETADA".equals(exam.state()))row.complete(exam.score(),Boolean.TRUE.equals(exam.passed()),exam.finishedAt());return mapper.toDomain(row);}
	@Override @Transactional(readOnly=true) public List<EvaluationAnswer> answers(UUID examId){return em.createQuery("select a from DiagnosticAnswerJpaEntity a where a.sessionId=:id order by a.id",DiagnosticAnswerJpaEntity.class).setParameter("id",examId).getResultList().stream().map(a->new EvaluationAnswer(a.getId(),examId,a.getActivityId(),a.isCorrect())).toList();}
	@Override public EvaluationAnswer saveAnswer(UUID examId,UUID activityId,UUID optionId,String text,boolean correct,Integer seconds){var row=new DiagnosticAnswerJpaEntity(examId,activityId,optionId,text,correct,seconds);em.persist(row);em.flush();return new EvaluationAnswer(row.getId(),examId,activityId,correct);}
}
